-- eval_scenarios: Eval scores per scenario, latest run
-- Per scenario in the latest complete eval run: end-to-end score, work score, essential facts found, questions the documents answered, and minutes. Reads public.eval_runs (simulated data only).
with latest as (select run_id from public.eval_runs order by run_id desc limit 1), s as (select scenario, step, metrics from public.eval_runs where run_id = (select run_id from latest) and scenario <> 'ALL') select scenario, max((metrics->'request_to_done'->>'mean')::numeric) filter (where step = 'end_to_end') as request_to_done, max((metrics->'meets_expected'->>'mean')::numeric) filter (where step = 'work') as meets_expected, max((metrics->'essential_share'->>'mean')::numeric) filter (where step = 'grill') as essential_share, max((metrics->'questions_docs_answer'->>'mean')::numeric) filter (where step = 'grill') as questions_docs_answer, max((metrics->'caveats_honest'->>'mean')::numeric) filter (where step = 'record') as caveats_honest, round(max((metrics->'seconds'->>'mean')::numeric) filter (where step = 'end_to_end') / 60, 1) as minutes from s group by scenario order by request_to_done nulls first, scenario;
